insert into public.roles(code,name,description,is_system,active,sort_order) values ('owner','Owner','Full tenant ownership and administration.',true,true,10),('admin','Administrator','Administrative access within a tenant.',true,true,20),('staff','Staff','Operational staff access granted through permissions.',true,true,30) on conflict(code) do update set name=excluded.name,description=excluded.description,is_system=excluded.is_system,active=excluded.active,sort_order=excluded.sort_order,updated_at=now();
insert into public.permissions(code,name,description,domain,active) values ('acquisitions.manage','Manage acquisitions','Operate acquisition workflow.','acquisitions',true),('acquisitions.view','View acquisitions','View purchases/acquisitions.','acquisitions',true),('audit.view','View audit history','View tenant audit history.','audit',true),('buying.manage','Manage buying','Operate buying requests and related workflow.','buying',true),('buying.view','View buying','View buying requests and buying workflow.','buying',true),('categories.manage','Manage categories','Create and manage tenant categories and dynamic fields.','catalogue',true),('categories.view','View categories','View tenant categories and field definitions.','catalogue',true),('customers.manage','Manage customers','Create and manage tenant customers.','customers',true),('customers.view','View customers','View tenant customers.','customers',true),('finance.manage','Manage finance','Manage financial operational records and payment workflow.','finance',true),('finance.view','View finance','View financial records and payment records.','finance',true),('fulfilment.manage','Manage fulfilment','Operate fulfilment, parcels and tracking.','fulfilment',true),('fulfilment.view','View fulfilment','View inbound and outbound fulfilment.','fulfilment',true),('inventory.manage','Manage inventory','Create and operate inventory workflow.','inventory',true),('inventory.view','View inventory','View inventory assets and history.','inventory',true),('messaging.manage','Manage staff messaging','Manage staff conversations and messaging administration.','messaging',true),('messaging.view','Use staff messaging','Use internal staff messaging where the subscription permits it.','messaging',true),('notification.manage','Manage notifications','Manage customer email sender settings, templates and notification switches','notifications',true),('notification.view','View notifications','View customer notification settings and delivery history','notifications',true),('offers.manage','Manage offers','Create, publish and manage offers.','offers',true),('offers.view','View offers','View customer offers.','offers',true),('orders.manage','Manage retail orders','Operate retail order workflow.','sales',true),('orders.view','View retail orders','View customer retail orders.','sales',true),('returns.manage','Manage returns','Operate return workflow and resolutions.','returns',true),('returns.view','View returns','View returns and resolutions.','returns',true),('selling.manage','Manage selling','Create, publish and manage listings and sales channels.','selling',true),('selling.view','View selling','View channels and listings.','selling',true),('staff.manage','Manage staff','Invite, change and deactivate staff memberships.','staff',true),('staff.view','View staff','View tenant staff and memberships.','staff',true),('tenant.manage','Manage business settings','Change tenant-level business settings.','tenant',true),('tenant.view','View business settings','View tenant and business settings.','tenant',true),('valuation.manage','Manage Trading Values','Create, approve and manage Trading Values and valuation rules.','valuation',true),('valuation.view','View Trading Values','View Trading Value results and history.','valuation',true),('website.manage','Manage Website','Create and edit tenant website configuration and draft content.','website',true),('website.publish','Publish Website','Publish a validated tenant website revision to the public site.','website',true) on conflict(code) do update set name=excluded.name,description=excluded.description,domain=excluded.domain,active=excluded.active,updated_at=now();
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from (values ('admin','acquisitions.manage'),('admin','acquisitions.view'),('admin','buying.manage'),('admin','buying.view'),('admin','categories.manage'),('admin','categories.view'),('admin','customers.manage'),('admin','customers.view'),('admin','finance.manage'),('admin','finance.view'),('admin','fulfilment.manage'),('admin','fulfilment.view'),('admin','inventory.manage'),('admin','inventory.view'),('admin','messaging.manage'),('admin','messaging.view'),('admin','notification.manage'),('admin','notification.view'),('admin','offers.manage'),('admin','offers.view'),('admin','orders.manage'),('admin','orders.view'),('admin','returns.manage'),('admin','returns.view'),('admin','selling.manage'),('admin','selling.view'),('admin','staff.view'),('admin','tenant.view'),('admin','valuation.manage'),('admin','valuation.view'),('admin','website.manage'),('admin','website.publish'),('owner','acquisitions.manage'),('owner','acquisitions.view'),('owner','audit.view'),('owner','buying.manage'),('owner','buying.view'),('owner','categories.manage'),('owner','categories.view'),('owner','customers.manage'),('owner','customers.view'),('owner','finance.manage'),('owner','finance.view'),('owner','fulfilment.manage'),('owner','fulfilment.view'),('owner','inventory.manage'),('owner','inventory.view'),('owner','messaging.manage'),('owner','messaging.view'),('owner','notification.manage'),('owner','notification.view'),('owner','offers.manage'),('owner','offers.view'),('owner','orders.manage'),('owner','orders.view'),('owner','returns.manage'),('owner','returns.view'),('owner','selling.manage'),('owner','selling.view'),('owner','staff.manage'),('owner','staff.view'),('owner','tenant.manage'),('owner','tenant.view'),('owner','valuation.manage'),('owner','valuation.view'),('owner','website.manage'),('owner','website.publish'),('staff','acquisitions.manage'),('staff','acquisitions.view'),('staff','buying.manage'),('staff','buying.view'),('staff','categories.view'),('staff','customers.manage'),('staff','customers.view'),('staff','fulfilment.manage'),('staff','fulfilment.view'),('staff','inventory.manage'),('staff','inventory.view'),('staff','messaging.manage'),('staff','messaging.view'),('staff','notification.view'),('staff','offers.manage'),('staff','offers.view'),('staff','orders.manage'),('staff','orders.view'),('staff','returns.manage'),('staff','returns.view'),('staff','selling.manage'),('staff','selling.view'),('staff','tenant.view'),('staff','valuation.view')) v(role_code,permission_code) join public.roles r on r.code=v.role_code join public.permissions p on p.code=v.permission_code on conflict do nothing;
insert into public.plan_features(plan_id,feature_code,enabled,config) select pl.id,v.feature_code,v.enabled,v.config::jsonb from (values ('catalogue.pre_filled',true,'{"product_limit":null,"category_limit":null,"subcategory_limit":null}'),('module.analytics',false,'{}'),('module.audit',false,'{}'),('module.buying',true,'{}'),('module.customer_portal',true,'{}'),('module.fulfilment',true,'{}'),('module.integrations',false,'{}'),('module.inventory',true,'{}'),('module.market_intelligence',true,'{}'),('module.offers',true,'{}'),('module.orders',true,'{}'),('module.selling',true,'{}'),('module.staff',false,'{"staff_limit":10}'),('module.staff_messaging',false,'{}'),('module.storefront',true,'{}'),('module.trade_in',true,'{}'),('module.valuation',true,'{"methods":["manual","rule"]}'),('website.editor',true,'{"logo_upload":true,"image_content":true,"colour_selection":true,"custom_categories":true,"template_selection":true,"custom_subcategories":true}'),('website.preview',true,'{}'),('website.publish',true,'{}')) v(feature_code,enabled,config) join public.plans pl on pl.code='enhanced' on conflict(plan_id,feature_code) do update set enabled=excluded.enabled,config=excluded.config,updated_at=now();
